+// RF-004: descuento opcional por línea (porcentaje 0–100), aplicado antes del total y redondeado al centavo.
+function totalLineaCentavos(item) {
+  const brutoCentavos = item.cantidad * item.precioUnitarioCentavos;
+  const pct = item.descuentoPorcentaje ?? 0;
+  if (typeof pct !== "number" || !Number.isFinite(pct) || pct < 0 || pct > 100)
+    throw new RangeError("Descuento inválido: debe estar entre 0 y 100");
+  return brutoCentavos - Math.round((brutoCentavos * pct) / 100);
+}
