diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..b9c7b1b 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,22 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+test("RF-004: descuento por línea antes del total, redondeado al centavo", () => {
+  const f = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 }]);
+  assert.equal(f.totalCentavos, 1800);
+  assert.equal(f.ivaCentavos, 234);
+  // redondeo al centavo: 3 × 0,33 Bs = 99 c, 10 % → 89,1 → 89
+  assert.equal(calcularFactura([{ cantidad: 3, precioUnitarioCentavos: 33, descuentoPorcentaje: 10 }]).totalCentavos, 89);
+  // sin descuento y 100 % son válidos; el descuento es opcional
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 500, descuentoPorcentaje: 0 }]).totalCentavos, 500);
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 500, descuentoPorcentaje: 100 }]).totalCentavos, 0);
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 500 }]).totalCentavos, 500);
+  // fuera de 0–100 se rechaza
+  for (const d of [-1, 101, NaN, "10"]) {
+    assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 500, descuentoPorcentaje: d }]), RangeError);
+  }
+});
